def valid(number):
    """Return True if number passes the Luhn check.

    The input is a string. Spaces are ignored. After removing spaces,
    the number must contain at least two characters, all of which are
    decimal digits.
    """
    if not isinstance(number, str):
        return False

    digits = number.replace(" ", "")
    if len(digits) < 2 or not digits.isdigit():
        return False

    total = 0
    for index, char in enumerate(reversed(digits)):
        digit = int(char)
        if index % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit

    return total % 10 == 0
